import{generate,clone,complete,won,move}from'./engine.js';
const $=s=>document.querySelector(s),colors=['#ff698f','#2cdbd5','#a475ff','#ffc747','#66b2ff','#9bdd75'],names=['rose','aqua','violet','gold','blue','lime'];
const icons={undo:'<path d="M9 5 3 11l6 6M3 11h11a7 7 0 0 1 0 14" transform="translate(1 -3)"/>',restart:'<path d="M20 10a8 8 0 1 1-5-6M15 1v5h5"/>',extra:'<path d="M12 4v16M4 12h16"/>',sound:'<path d="m11 4-5 4H3v8h3l5 4ZM15 8q5 4 0 8M18 4q9 8 0 16"/>',mute:'<path d="m11 4-5 4H3v8h3l5 4ZM16 9l6 6m0-6-6 6"/>'};const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`;['undo','restart','extra'].forEach(n=>$('#'+n+' .circle').innerHTML=icon(n));
let level=1,board=[],history=[],selected=-1,busy=false,moves=0,sound=false,extra=false,audio;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{let s=JSON.parse(localStorage.getItem('prism-pour'));if(s&&Number.isInteger(s.level)&&s.level>0&&s.level<=100000){level=s.level;sound=!!s.sound;let n=generate(level).board.length;if(Array.isArray(s.board)&&s.board.length>=n&&s.board.length<=n+1&&s.board.every(t=>Array.isArray(t)&&t.length<=4&&t.every(c=>Number.isInteger(c)&&c>=0&&c<6))){let counts=Array(6).fill(0);s.board.flat().forEach(c=>counts[c]++);if(counts.every(c=>c===0||c===4)&&counts.reduce((a,b)=>a+b,0)===(n-2)*4){board=clone(s.board);moves=Math.max(0,s.moves||0);extra=board.length>n;}}}}catch{}
if(!board.length)board=generate(level).board;
function save(){try{localStorage.setItem('prism-pour',JSON.stringify({level,board,moves,sound}));}catch{}}
function tone(freq=500,duration=.12){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.7,audio.currentTime+duration);g.gain.setValueAtTime(.065,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function vibrate(n){if(!reduced)navigator.vibrate?.(n)}
function tubeSVG(t,id){let segments=t.map((c,i)=>{let y=166-(i+1)*34;return `<g><rect x="10" y="${y}" width="62" height="35" fill="${colors[c]}"/><rect x="10" y="${y}" width="62" height="35" fill="url(#shade${id})"/><ellipse cx="41" cy="${y}" rx="31" ry="4" fill="${colors[c]}"/><path d="M11 ${y}Q41 ${y+7}71 ${y}" fill="none" stroke="#ffffff77" stroke-width="1.4"/></g>`}).join('');return `<svg viewBox="0 0 82 184" aria-hidden="true"><defs><clipPath id="clip${id}"><path d="M10 11H72V143Q72 172 41 173Q10 172 10 143Z"/></clipPath><linearGradient id="glass${id}"><stop stop-color="#e1eaff88"/><stop offset=".1" stop-color="#d3deff0a"/><stop offset=".5" stop-color="#cce1ff02"/><stop offset=".85" stop-color="#bacaff15"/><stop offset="1" stop-color="#dce5ff77"/></linearGradient><linearGradient id="shade${id}"><stop stop-color="#fff5"/><stop offset=".17" stop-color="#fff0"/><stop offset=".8" stop-color="#0000"/><stop offset="1" stop-color="#0004"/></linearGradient></defs><path d="M7 10H75V143Q75 177 41 177Q7 177 7 143Z" fill="url(#glass${id})" stroke="#c7d3f4aa" stroke-width="1.5"/><g clip-path="url(#clip${id})">${segments}</g><path d="M11 15V142Q11 171 40 173" fill="none" stroke="#fff9" stroke-width="2"/><path d="M71 17V141Q71 165 57 169" fill="none" stroke="#c9d8ff88" stroke-width="2"/><path d="M16 21V130" stroke="#fff4" stroke-width="3" stroke-linecap="round"/><ellipse cx="41" cy="10" rx="34" ry="5" fill="#13183077" stroke="#f3f2ffe0" stroke-width="1.5"/><ellipse cx="41" cy="11" rx="30" ry="3" fill="none" stroke="#b3c4ef88"/></svg>`}
function render(){let container=$('#board');container.classList.toggle('many',board.length>6);container.innerHTML=board.map((t,i)=>`<button class="tube ${complete(t)?'done':''} ${selected===i?'selected':''} ${selected>=0&&move(board,selected,i)?'valid':''}" aria-label="Tube ${i+1}: ${t.length?t.map(c=>names[c]).join(', ')+', bottom to top':'empty'}${complete(t)?', sorted':''}" aria-pressed="${selected===i}" data-i="${i}">${tubeSVG(t,i)}</button>`).join('');container.querySelectorAll('button').forEach(b=>b.onclick=()=>choose(+b.dataset.i));$('#level').textContent='LEVEL '+String(level).padStart(2,'0');$('#moves').textContent=moves;$('#sorted').textContent=board.filter(complete).length+' of '+(generateCount())+' sorted';$('#undo').disabled=!history.length||busy;$('#restart').disabled=busy;$('#extra').disabled=extra||busy;$('#sound').innerHTML=icon(sound?'sound':'mute');$('#sound').setAttribute('aria-label',sound?'Turn sound off':'Turn sound on');}
function generateCount(){return Math.min(6,4+Math.floor((level-1)/4))}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function choose(i){if(busy||won(board))return;if(selected<0){if(!board[i].length)return;selected=i;tone(570,.08);vibrate(8);render();return}if(selected===i){selected=-1;render();return}let a=selected,result=move(board,a,i);if(!result){selected=board[i].length?i:selected;render();let el=$(`[data-i="${i}"]`);el.classList.add('shake');$('#message').textContent='Match the top color, or use an empty tube.';tone(160,.13);return}busy=true;history.push({board:clone(board),moves,extra});let from=$(`[data-i="${a}"]`),to=$(`[data-i="${i}"]`),f=from.getBoundingClientRect(),t=to.getBoundingClientRect();selected=-1;$('#undo').disabled=true;$('#restart').disabled=true;$('#extra').disabled=true;
if(!reduced){let ghost=document.createElement('div');ghost.className='pour-ghost';ghost.innerHTML=tubeSVG(board[a],'ghost');ghost.style.cssText=`left:${f.left}px;top:${f.top}px;width:${f.width}px`;document.body.append(ghost);from.style.opacity='.15';let dx=t.left+t.width/2-f.left-f.width/2-26,dy=t.top-f.top-50;await ghost.animate([{transform:'translate(0,0) rotate(0deg)'},{transform:`translate(${dx}px,${dy}px) rotate(65deg)`}],{duration:300,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'}).finished;let stream=document.createElement('div');stream.className='stream';stream.style.cssText=`left:${t.left+t.width/2-3}px;top:${t.top-29}px;height:${Math.max(42,35+(4-board[i].length-result.count)*t.height*.185)}px;background:${colors[result.color]};color:${colors[result.color]}`;document.body.append(stream);tone(660,.24);await pause(290);stream.remove();board=result.board;render();await ghost.animate([{transform:`translate(${dx}px,${dy}px) rotate(65deg)`},{transform:'translate(0,0) rotate(0deg)',opacity:0}],{duration:240,easing:'ease-in',fill:'forwards'}).finished;ghost.remove();}else{board=result.board;tone(660,.15)}moves++;busy=false;render();save();$(`[data-i="${i}"]`).classList.add('land');$('#message').textContent='Tap a tube, then tap another to pour.';vibrate(12);if(complete(board[i])){burst(t.left+t.width/2,t.top+t.height*.45,26);[660,830,990].forEach((f,j)=>setTimeout(()=>tone(f,.24),j*85));$('#message').textContent='One color. Perfect harmony.'}if(won(board)){await pause(reduced?0:500);celebrate();}}
function celebrate(){$('#win-text').textContent=`Level ${level} complete in ${moves} pours. Take a breath. Enjoy the little win.`;if(!$('#win-dialog').open)$('#win-dialog').showModal();if(!reduced){burst(innerWidth*.3,innerHeight*.4,70);burst(innerWidth*.7,innerHeight*.4,70)}}
function reset(){board=generate(level).board;history=[];moves=0;extra=false;selected=-1;render();save();$('#message').textContent='Tap a tube, then tap another to pour.'}
$('#undo').onclick=()=>{if(busy||!history.length)return;let s=history.pop();board=s.board;moves=s.moves;extra=s.extra;selected=-1;render();save();tone(390)};$('#restart').onclick=()=>{if(!busy)reset()};$('#extra').onclick=()=>{if(busy||extra)return;history.push({board:clone(board),moves,extra});board.push([]);extra=true;selected=-1;render();save();$('#message').textContent='A little breathing room. Always free.';tone(780)};$('#sound').onclick=()=>{sound=!sound;render();save();tone(720)};$('#help').onclick=()=>$('#help-dialog').showModal();$('#got-it').onclick=$('.close').onclick=()=>$('#help-dialog').close();$('#next').onclick=()=>{$('#win-dialog').close();level++;reset()};$('#replay').onclick=()=>{$('#win-dialog').close();reset()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=-1;render()}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!document.querySelector('dialog[open]')){e.preventDefault();$('#undo').click()}});
let particles=[],raf=0,ctx=$('#particles').getContext('2d');function burst(x,y,n){if(reduced)return;for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*8,vy:-Math.random()*7-1,life:1,size:Math.random()*4+2,c:colors[i%colors.length]});if(!raf)raf=requestAnimationFrame(frame)}function frame(){let c=ctx.canvas;if(c.width!==innerWidth||c.height!==innerHeight){c.width=innerWidth;c.height=innerHeight}ctx.clearRect(0,0,c.width,c.height);particles=particles.filter(p=>p.life>0);for(let p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.12;p.life-=.015;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;raf=particles.length?requestAnimationFrame(frame):0}render();if(won(board))celebrate();
